using System.Security.Cryptography;using System.Text;using System.Text.Json;using Cyno.Licensing;using Xunit;
namespace OpenDS4AI.Tests;
public class LicenseTests
{
    private static (ECDsa Issuer,ECDsa Device,DeviceRequest Request) Fixture(){var issuer=ECDsa.Create(ECCurve.NamedCurves.nistP256);var device=ECDsa.Create(ECCurve.NamedCurves.nistP256);string pub=Convert.ToBase64String(device.ExportSubjectPublicKeyInfo()),hash=new('A',64);return(issuer,device,new(1,LicenseProtocol.Product,Guid.NewGuid().ToString("N"),LicenseProtocol.DeviceId(hash,pub),hash,pub,DateTimeOffset.UtcNow,"test"));}
    [Fact]public void ValidSignedLicenseActivatesOnlyMatchingDevice(){var f=Fixture();using var issuer=f.Issuer;using var device=f.Device;var now=DateTimeOffset.UtcNow;var claims=LicenseProtocol.CreateClaims(f.Request,"Test",issuer.ExportSubjectPublicKeyInfoPem(),now);string signed=LicenseProtocol.Sign(claims,issuer);Assert.True(LicenseProtocol.Verify(signed,issuer.ExportSubjectPublicKeyInfoPem(),f.Request.DeviceId,f.Request.DevicePublicKey,now).Valid);Assert.False(LicenseProtocol.Verify(signed,issuer.ExportSubjectPublicKeyInfoPem(),new string('B',64),f.Request.DevicePublicKey,now).Valid);Assert.False(LicenseProtocol.Verify(signed,issuer.ExportSubjectPublicKeyInfoPem(),f.Request.DeviceId,"altra chiave",now).Valid);}
    [Fact]public void AlteredClaimsAndWrongIssuerFail(){var f=Fixture();using var issuer=f.Issuer;using var device=f.Device;using var other=ECDsa.Create(ECCurve.NamedCurves.nistP256);var now=DateTimeOffset.UtcNow;string signed=LicenseProtocol.Sign(LicenseProtocol.CreateClaims(f.Request,"Test",issuer.ExportSubjectPublicKeyInfoPem(),now),issuer);Assert.False(LicenseProtocol.Verify(signed,other.ExportSubjectPublicKeyInfoPem(),f.Request.DeviceId,f.Request.DevicePublicKey,now).Valid);var envelope=JsonSerializer.Deserialize<SignedEnvelope>(signed)!;byte[] bytes=Convert.FromBase64String(envelope.Payload);bytes[^2]^=1;string changed=JsonSerializer.Serialize(envelope with {Payload=Convert.ToBase64String(bytes)});Assert.False(LicenseProtocol.Verify(changed,issuer.ExportSubjectPublicKeyInfoPem(),f.Request.DeviceId,f.Request.DevicePublicKey,now).Valid);}
    [Fact]public void ExpiredFutureAndOtherProductFail(){var f=Fixture();using var issuer=f.Issuer;using var device=f.Device;var now=DateTimeOffset.UtcNow;var c=LicenseProtocol.CreateClaims(f.Request,"Test",issuer.ExportSubjectPublicKeyInfoPem(),now);foreach(var bad in new[]{c with {ExpiresUtc=now.AddSeconds(-1)},c with {NotBeforeUtc=now.AddHours(1)},c with {Product="Other"},c with {Schema=99}})Assert.False(LicenseProtocol.Verify(LicenseProtocol.Sign(bad,issuer),issuer.ExportSubjectPublicKeyInfoPem(),f.Request.DeviceId,f.Request.DevicePublicKey,now).Valid);}
    [Theory][InlineData("")][InlineData("{}")] [InlineData("not json")]public void MissingAndMalformedLicensesFailClosed(string text){var f=Fixture();using var i=f.Issuer;using var d=f.Device;Assert.False(LicenseProtocol.Verify(text,i.ExportSubjectPublicKeyInfoPem(),f.Request.DeviceId,f.Request.DevicePublicKey,DateTimeOffset.UtcNow).Valid);}
    [Fact]public void OversizedLicenseRejected(){var f=Fixture();using var i=f.Issuer;using var d=f.Device;Assert.False(LicenseProtocol.Verify(new string('A',40000),i.ExportSubjectPublicKeyInfoPem(),f.Request.DeviceId,f.Request.DevicePublicKey,DateTimeOffset.UtcNow).Valid);}
    [Fact]public void DeviceRequestsRequireProof(){var f=Fixture();using var i=f.Issuer;using var d=f.Device;Assert.Equal(f.Request,LicenseProtocol.ReadRequest(LicenseProtocol.Sign(f.Request,d)));Assert.Throws<InvalidDataException>(()=>LicenseProtocol.ReadRequest(LicenseProtocol.Sign(f.Request with {DeviceId=new string('B',64)},d)));Assert.Throws<InvalidDataException>(()=>LicenseProtocol.ReadRequest(LicenseProtocol.Sign(f.Request,i)));}
}
